import React, { useState } from 'react';
import './Header.css';

function Header() {
  const [showExplore, setShowExplore] = useState(false);

  const handleExploreToggle = () => {
    setShowExplore((prev) => !prev);
  };

  const exploreCategories = [
    'Trending',
    'Music',
    'Gaming',
    'News',
    'Sports',
    'Education',
    'Movies',
  ];

  return (
    <>
      <header className="header">
        <div className="container">
          <i className="fa-brands fa-youtube youtube"></i>

          <div className="icons">
            <button className="explore-button" onClick={handleExploreToggle}>
              Explore <i className={`fas ${showExplore ? 'fa-chevron-up' : 'fa-chevron-down'}`}></i>
            </button>
          </div>
        </div>
      </header>

      {showExplore && (
        <nav className="explore-nav">
          <ul className="explore-dropdown">
            {exploreCategories.map((category, index) => (
              <li key={index} className="explore-item">
                {category}
              </li>
            ))}
          </ul>
        </nav>
      )}
    </>
  );
}

export default Header;
